import express from "express";const vault=express();vault.use(express.json());let treasury=0;vault.post("/collect", (req,res)=>{treasury+=req.body.amount||10; res.json({ company:"SOVEREIGN HOLDINGS - TREASURY VAULT", collected:req.body.amount, total_treasury:treasury, status:"TREASURY_GROWING" });});vault.get("/", (req,res)=>res.json({ company:"SOVEREIGN HOLDINGS - TREASURY VAULT", total:treasury, sovereign_holdings:true }));vault.listen(3005,()=>console.log("TREASURY VAULT 3005"));